// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address caller, uint256 rollTarget) public {
        vm.assume(uint160(caller) > 255 && caller != address(this) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);

        vm.assume(caller != address(0));
        rollTarget = bound(rollTarget, 1, type(uint64).max);

        vm.warp(1);

        uint256 target = rollTarget;
        uint256 mod = target % 15;
        if (mod != 0) {
            uint256 shift = 15 - mod;
            target = target + shift;
        }
        vm.roll(uint64(target));

        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        assertTrue(address(c).balance == 0);
    }
}
